PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY,civilization_id TEXT UNIQUE,email TEXT UNIQUE NOT NULL,first_name TEXT,last_name TEXT,display_name TEXT,language TEXT NOT NULL DEFAULT 'en',country TEXT,status TEXT NOT NULL DEFAULT 'pending',email_verified_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS consents(id TEXT PRIMARY KEY,person_id TEXT NOT NULL,consent_type TEXT NOT NULL,consent_version TEXT NOT NULL,granted INTEGER NOT NULL,source TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS interest_topics(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,name_zh TEXT NOT NULL,name_en TEXT NOT NULL,description_zh TEXT,description_en TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS topic_subscriptions(person_id TEXT NOT NULL,topic_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',confirmed_at INTEGER,unsubscribed_at INTEGER,updated_at INTEGER NOT NULL,PRIMARY KEY(person_id,topic_id),FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE,FOREIGN KEY(topic_id) REFERENCES interest_topics(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS briefs(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,pillar TEXT NOT NULL,issue_no TEXT,title_zh TEXT NOT NULL,title_en TEXT NOT NULL,summary_zh TEXT,summary_en TEXT,pdf_zh_en_url TEXT,published_at INTEGER,status TEXT NOT NULL DEFAULT 'draft',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,type TEXT NOT NULL,topic_id TEXT,subject_zh TEXT,subject_en TEXT,body_ref TEXT,status TEXT NOT NULL DEFAULT 'draft',scheduled_at INTEGER,sent_at INTEGER,created_by TEXT,created_at INTEGER NOT NULL,FOREIGN KEY(topic_id) REFERENCES interest_topics(id));
CREATE TABLE IF NOT EXISTS campaign_deliveries(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL,person_id TEXT NOT NULL,provider_message_id TEXT,status TEXT NOT NULL DEFAULT 'queued',sent_at INTEGER,delivered_at INTEGER,bounced_at INTEGER,complained_at INTEGER,opened_at INTEGER,clicked_at INTEGER,error TEXT,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS donations(id TEXT PRIMARY KEY,person_id TEXT,donor_type TEXT NOT NULL DEFAULT 'individual',amount_minor INTEGER,currency TEXT,purpose TEXT,payment_provider TEXT,provider_reference TEXT,status TEXT NOT NULL DEFAULT 'pending',donated_at INTEGER,receipt_reference TEXT,notes TEXT,created_at INTEGER NOT NULL,FOREIGN KEY(person_id) REFERENCES people(id));
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY,type TEXT NOT NULL,title_zh TEXT NOT NULL,title_en TEXT NOT NULL,description_zh TEXT,description_en TEXT,starts_at INTEGER,ends_at INTEGER,location_text TEXT,capacity INTEGER,status TEXT NOT NULL DEFAULT 'draft',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS activity_registrations(activity_id TEXT NOT NULL,person_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'registered',created_at INTEGER NOT NULL,PRIMARY KEY(activity_id,person_id),FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS votes(id TEXT PRIMARY KEY,title_zh TEXT NOT NULL,title_en TEXT NOT NULL,description_zh TEXT,description_en TEXT,opens_at INTEGER,closes_at INTEGER,eligibility_rule TEXT,status TEXT NOT NULL DEFAULT 'draft',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS vote_options(id TEXT PRIMARY KEY,vote_id TEXT NOT NULL,label_zh TEXT NOT NULL,label_en TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_ballots(id TEXT PRIMARY KEY,vote_id TEXT NOT NULL,person_id TEXT NOT NULL,option_id TEXT NOT NULL,cast_at INTEGER NOT NULL,UNIQUE(vote_id,person_id),FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE,FOREIGN KEY(option_id) REFERENCES vote_options(id));
CREATE TABLE IF NOT EXISTS initiatives(id TEXT PRIMARY KEY,title_zh TEXT NOT NULL,title_en TEXT NOT NULL,description_zh TEXT,description_en TEXT,goal_text TEXT,opens_at INTEGER,closes_at INTEGER,status TEXT NOT NULL DEFAULT 'draft',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS initiative_support(initiative_id TEXT NOT NULL,person_id TEXT NOT NULL,supported_at INTEGER NOT NULL,PRIMARY KEY(initiative_id,person_id),FOREIGN KEY(initiative_id) REFERENCES initiatives(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,actor_type TEXT NOT NULL,actor_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,detail_json TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_people_status ON people(status,created_at);
CREATE INDEX IF NOT EXISTS idx_deliveries_campaign ON campaign_deliveries(campaign_id,status);
CREATE INDEX IF NOT EXISTS idx_donations_person ON donations(person_id,donated_at);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_log(entity_type,entity_id,created_at);

CREATE TABLE IF NOT EXISTS email_verifications(id INTEGER PRIMARY KEY AUTOINCREMENT,person_id TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,created_at INTEGER NOT NULL,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
